import type { ImgHTMLAttributes } from "react";

type CampaignImageName =
  | "home"
  | "lake"
  | "observatory"
  | "portal-arch"
  | "portal-ridge"
  | "portal-rocks";

type CampaignImageProps = Omit<
  ImgHTMLAttributes<HTMLImageElement>,
  "alt" | "src" | "srcSet"
> & {
  alt: string;
  image: CampaignImageName;
  pictureClassName?: string;
};

export function CampaignImage({
  alt,
  image,
  pictureClassName,
  sizes = "100vw",
  ...imageProps
}: CampaignImageProps) {
  const base = `/images/landing-v2/${image}`;

  return (
    <picture className={pictureClassName}>
      <source
        type="image/webp"
        srcSet={`${base}-1200.webp 1200w, ${base}-2400.webp 2400w`}
        sizes={sizes}
      />
      <img src={`${base}.png`} alt={alt} sizes={sizes} {...imageProps} />
    </picture>
  );
}

import { useEffect } from "react";

import { ExtensionsSection } from "./components/extensions-section";
import { FAQ } from "./components/faq";
import { Footer } from "./components/footer";
import { HowItWorks } from "./components/how-it-works";
import { LandingHeader } from "./components/landing-header";
import { LandingHero } from "./components/landing-hero";
import { LandingPricing } from "./components/landing-pricing";
import { LandingStats } from "./components/landing-stats";
import { WhySaveIt } from "./components/why-saveit";

export function App() {
  useEffect(() => {
    const elements = Array.from(
      document.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (!("IntersectionObserver" in window)) {
      elements.forEach((element) => element.classList.add("is-visible"));
      return;
    }

    document.documentElement.classList.add("reveal-ready");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { rootMargin: "0px 0px -8%", threshold: 0.12 },
    );

    elements.forEach((element) => observer.observe(element));
    return () => observer.disconnect();
  }, []);

  return (
    <div className="landing-page" id="top">
      <a className="skip-link" href="#main-content">
        Skip to content
      </a>
      <LandingHeader />
      <main id="main-content">
        <LandingHero />
        <WhySaveIt />
        <HowItWorks />
        <LandingStats />
        <ExtensionsSection />
        <LandingPricing />
        <FAQ />
      </main>
      <Footer />
    </div>
  );
}

