@import "tailwindcss";
@import "@fontsource-variable/geist";

@source "./**/*.{ts,tsx}";

:root {
  font-family: "Geist Variable", "Helvetica Neue", Arial, sans-serif;
  color: #f1f4ed;
  background: #08130f;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --canvas: #08130f;
  --canvas-soft: #0d1c16;
  --canvas-raised: #13251d;
  --pine: #183a2d;
  --mist: #f1f4ed;
  --mist-muted: #a8b5ac;
  --fog: #dfe6df;
  --coral: #ff7351;
  --coral-strong: #ff4f2e;
  --mint: #9fe5c0;
  --lilac: #c7bbc8;
  --line: rgba(241, 244, 237, 0.13);
  --line-strong: rgba(241, 244, 237, 0.24);
  --display: "Iowan Old Style", "Baskerville", "Times New Roman", serif;
  --utility: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --shadow: 0 30px 100px rgba(0, 0, 0, 0.34);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 88px;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--canvas);
}

body,
button,
a,
summary {
  -webkit-tap-highlight-color: transparent;
}

button,
input,
summary {
  font: inherit;
}

button,
a {
  color: inherit;
}

a {
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

button {
  border: 0;
}

::selection {
  color: var(--canvas);
  background: var(--mint);
}

:focus-visible {
  outline: 2px solid var(--mint);
  outline-offset: 4px;
}

.sr-only {
  position: absolute;
  overflow: hidden;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: fixed;
  z-index: 100;
  top: 12px;
  left: 12px;
  padding: 10px 14px;
  color: var(--canvas);
  background: var(--mist);
  border-radius: 999px;
  transform: translateY(-160%);
  transition: transform 180ms ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.landing-page {
  position: relative;
  overflow-x: hidden;
  overflow-x: clip;
  color: var(--mist);
  background:
    radial-gradient(circle at 82% 8%, rgba(255, 115, 81, 0.08), transparent 28rem),
    var(--canvas);
}

.landing-page::before {
  position: fixed;
  z-index: 20;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
}

.section {
  position: relative;
  padding: clamp(5.5rem, 10vw, 9.5rem) 1.25rem;
}

.section-shell,
.header-shell {
  width: min(100%, 1240px);
  margin-inline: auto;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 1.2rem;
  color: var(--mint);
  font-family: var(--utility);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  line-height: 1.2;
  text-transform: uppercase;
}

.section h2,
.closing-copy h2 {
  max-width: 760px;
  margin: 0;
  font-family: var(--display);
  font-size: clamp(2.8rem, 5.3vw, 5.8rem);
  font-weight: 400;
  letter-spacing: -0.055em;
  line-height: 0.94;
}

.section-lead {
  max-width: 620px;
  margin: 1.6rem 0 0;
  color: var(--mist-muted);
  font-size: clamp(1.02rem, 1.4vw, 1.2rem);
  line-height: 1.65;
}

.section-heading {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr);
  gap: clamp(2rem, 7vw, 8rem);
  align-items: end;
  margin-bottom: clamp(2.8rem, 6vw, 5.6rem);
}

.section-heading .section-lead {
  margin: 0 0 0.4rem;
}

.button {
  display: inline-flex;
  min-height: 46px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 0.75rem 1.15rem;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 650;
  line-height: 1;
  transition:
    color 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.button:hover {
  transform: translateY(-2px);
}

.button-default {
  color: var(--canvas);
  background: var(--mist);
}

.button-default:hover {
  color: #08130f;
  background: var(--mint);
}

.button-outline {
  color: var(--mist);
  background: rgba(241, 244, 237, 0.04);
  border-color: var(--line);
  backdrop-filter: blur(16px);
}

.button-outline:hover {
  background: rgba(241, 244, 237, 0.1);
  border-color: var(--line-strong);
}

.reveal-ready [data-reveal] {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity 700ms cubic-bezier(0.2, 0.72, 0.2, 1),
    transform 700ms cubic-bezier(0.2, 0.72, 0.2, 1);
}

.reveal-ready [data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

/* Header */

.site-header {
  position: fixed;
  z-index: 50;
  top: 0;
  right: 0;
  left: 0;
  padding: 0.75rem 1.25rem;
  transition:
    padding 220ms ease,
    background-color 220ms ease;
}

.site-header.is-scrolled {
  padding-top: 0.5rem;
}

.header-shell {
  display: grid;
  min-height: 56px;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 0.5rem 0.65rem 0.5rem 0.85rem;
  background: rgba(8, 19, 15, 0.58);
  border: 1px solid rgba(241, 244, 237, 0.11);
  border-radius: 18px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.12);
  backdrop-filter: blur(22px) saturate(130%);
}

.is-scrolled .header-shell {
  background: rgba(8, 19, 15, 0.88);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  width: fit-content;
  color: var(--mist);
  font-size: 0.98rem;
  font-weight: 690;
  letter-spacing: -0.025em;
}

.brand-mark {
  display: inline-flex;
  width: 30px;
  height: 30px;
  align-items: center;
  justify-content: center;
  color: var(--canvas);
  background: var(--coral);
  border-radius: 10px 10px 5px 5px;
  box-shadow: 0 0 26px rgba(255, 115, 81, 0.26);
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: clamp(1.1rem, 2.4vw, 2.2rem);
}

.desktop-nav a {
  position: relative;
  color: #aab6ae;
  font-size: 0.78rem;
  font-weight: 560;
  transition: color 160ms ease;
}

.desktop-nav a::after {
  position: absolute;
  right: 0;
  bottom: -8px;
  left: 0;
  height: 1px;
  content: "";
  background: var(--mint);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 180ms ease;
}

.desktop-nav a:hover {
  color: var(--mist);
}

.desktop-nav a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.header-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 0.5rem;
}

.header-actions .button {
  min-height: 40px;
  padding: 0.65rem 1rem;
  font-size: 0.78rem;
}

.header-sign-in {
  border-color: transparent;
  background: transparent;
}

.header-sign-in:hover {
  background: rgba(241, 244, 237, 0.07);
}

.menu-button {
  display: none;
  width: 42px;
  height: 42px;
  align-items: center;
  justify-content: center;
  color: var(--mist);
  background: rgba(241, 244, 237, 0.07);
  border: 1px solid var(--line);
  border-radius: 13px;
  cursor: pointer;
}

.mobile-nav {
  visibility: hidden;
  overflow: hidden;
  width: min(calc(100% - 2.5rem), 1240px);
  max-height: 0;
  margin: 0.45rem auto 0;
  opacity: 0;
  background: rgba(8, 19, 15, 0.96);
  border: 1px solid transparent;
  border-radius: 18px;
  backdrop-filter: blur(24px);
  transition:
    max-height 240ms ease,
    opacity 180ms ease,
    visibility 180ms ease,
    border-color 180ms ease;
}

.mobile-nav nav {
  display: grid;
  gap: 0;
  padding: 0.65rem;
}

.mobile-nav a:not(.button) {
  padding: 0.95rem 0.85rem;
  color: var(--mist-muted);
  border-bottom: 1px solid var(--line);
  font-size: 0.95rem;
}

.mobile-nav-cta {
  margin-top: 0.65rem;
}

.mobile-nav.is-open {
  visibility: visible;
  max-height: 520px;
  opacity: 1;
  border-color: var(--line);
}

/* Hero */

.hero {
  position: relative;
  display: flex;
  min-height: 100svh;
  align-items: center;
  padding: 8.4rem 1.25rem 5rem;
  isolation: isolate;
}

.hero-glow {
  position: absolute;
  z-index: -1;
  top: -14rem;
  right: -12rem;
  width: 42rem;
  height: 42rem;
  background: radial-gradient(circle, rgba(255, 115, 81, 0.15), transparent 64%);
  filter: blur(10px);
}

.hero-shell {
  display: grid;
  width: min(100%, 1340px);
  grid-template-columns: minmax(0, 0.95fr) minmax(480px, 0.8fr);
  gap: clamp(2rem, 6vw, 6.5rem);
  align-items: center;
  margin-inline: auto;
}

.hero-copy {
  position: relative;
  z-index: 2;
  padding-left: clamp(0rem, 2vw, 2rem);
}

.hero-eyebrow {
  margin-bottom: 2.2rem;
}

.eyebrow-dot {
  width: 7px;
  height: 7px;
  background: var(--coral);
  border-radius: 50%;
  box-shadow: 0 0 20px rgba(255, 115, 81, 0.7);
}

.hero h1 {
  margin: 0;
  color: var(--mist);
  font-size: clamp(3.6rem, 7.3vw, 8.2rem);
  font-weight: 780;
  letter-spacing: -0.075em;
  line-height: 0.78;
  white-space: nowrap;
}

.hero-promise {
  margin: 2.1rem 0 0;
  color: var(--coral);
  font-family: var(--display);
  font-size: clamp(2.35rem, 4.5vw, 5.2rem);
  font-style: italic;
  letter-spacing: -0.055em;
  line-height: 0.94;
}

.hero-support {
  max-width: 610px;
  margin: 1.55rem 0 0;
  color: #b5c0b8;
  font-size: clamp(1rem, 1.45vw, 1.18rem);
  line-height: 1.66;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin-top: 2.2rem;
}

.hero-actions .button {
  min-height: 50px;
  padding-inline: 1.35rem;
}

.hero-primary-cta {
  color: var(--canvas);
  background: var(--mist);
  box-shadow: 0 14px 45px rgba(0, 0, 0, 0.22);
}

.hero-primary-cta:hover {
  color: var(--canvas);
  background: var(--mint);
}

.hero-proofline {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 1.25rem 0 0;
  color: #73847a;
  font-family: var(--utility);
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.hero-proofline::before {
  width: 24px;
  height: 1px;
  content: "";
  background: var(--coral);
}

.hero-visual {
  position: relative;
  min-width: 0;
  padding: 1.1rem 1.1rem 2.6rem;
}

.hero-portal-line {
  position: absolute;
  z-index: 0;
  inset: -1rem -1rem 1.4rem;
  border: 1px solid rgba(159, 229, 192, 0.3);
  border-bottom-color: transparent;
  border-radius: 48% 48% 28px 28px;
  animation: portal-breathe 5.5s ease-in-out infinite;
}

.hero-image-frame {
  position: relative;
  z-index: 1;
  overflow: hidden;
  aspect-ratio: 0.82;
  background: var(--canvas-raised);
  border: 1px solid rgba(241, 244, 237, 0.24);
  border-radius: 50% 50% 34px 34px;
  box-shadow: var(--shadow);
}

.hero-picture,
.hero-image {
  width: 100%;
  height: 100%;
}

.hero-picture {
  display: block;
}

.hero-image {
  object-fit: cover;
  object-position: 55% center;
  transform: scale(1.045);
  animation: cinematic-drift 16s ease-in-out infinite alternate;
}

.hero-image-wash {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(8, 19, 15, 0.02) 45%, rgba(8, 19, 15, 0.66) 100%),
    linear-gradient(90deg, rgba(255, 115, 81, 0.08), transparent 48%);
}

.save-toast,
.return-card {
  position: absolute;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 0.85rem;
  color: var(--mist);
  background: rgba(8, 19, 15, 0.78);
  border: 1px solid rgba(241, 244, 237, 0.2);
  border-radius: 16px;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(18px);
}

.save-toast {
  top: 18%;
  left: 7%;
  animation: float-one 5.2s ease-in-out infinite;
}

.save-toast-icon,
.return-card-icon {
  display: inline-flex;
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  color: var(--canvas);
  background: var(--mint);
  border-radius: 11px;
}

.save-toast span,
.return-card span {
  font-size: 0.76rem;
  font-weight: 640;
  line-height: 1.25;
}

.save-toast small,
.return-card small {
  display: block;
  margin-bottom: 3px;
  color: #9cad9f;
  font-family: var(--utility);
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.return-card {
  right: 5%;
  bottom: 8%;
  max-width: 280px;
  animation: float-two 6.2s ease-in-out infinite;
}

.return-card-icon {
  color: var(--mist);
  background: var(--coral);
}

.return-card > svg {
  color: var(--mint);
}

.hero-visual-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  justify-content: space-between;
  padding: 0 1.4rem;
  color: #73847a;
  font-family: var(--utility);
  font-size: 0.6rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.hero-scroll {
  position: absolute;
  bottom: 1.5rem;
  left: 50%;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  color: #65746b;
  font-family: var(--utility);
  font-size: 0.61rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transform: translateX(-50%);
}

.hero-scroll svg {
  animation: scroll-prompt 1.8s ease-in-out infinite;
}

/* Transformation */

.transformation {
  background:
    linear-gradient(180deg, rgba(13, 28, 22, 0), var(--canvas-soft) 18%, var(--canvas-soft) 82%, rgba(13, 28, 22, 0)),
    var(--canvas);
}

.transformation-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(460px, 1fr);
  gap: clamp(3rem, 9vw, 9rem);
  align-items: center;
}

.transformation-copy h2 {
  max-width: 620px;
}

.friction-list {
  display: grid;
  gap: 0;
  margin-top: 2.7rem;
  border-top: 1px solid var(--line);
}

.friction-item {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 0.75rem;
  align-items: center;
  padding: 1rem 0;
  color: #88998e;
  border-bottom: 1px solid var(--line);
  font-size: 0.9rem;
}

.friction-item svg {
  color: #627269;
}

.friction-answer {
  color: var(--mist);
}

.friction-answer svg {
  color: var(--coral);
}

.memory-stack {
  position: relative;
  padding: clamp(1rem, 2vw, 1.6rem);
  background:
    radial-gradient(circle at 70% 18%, rgba(255, 115, 81, 0.12), transparent 16rem),
    #0a1712;
  border: 1px solid var(--line);
  border-radius: 30px;
  box-shadow: var(--shadow);
}

.memory-stack::before {
  position: absolute;
  top: -17px;
  left: 11%;
  width: 78%;
  height: 18px;
  content: "";
  background: rgba(159, 229, 192, 0.08);
  border: 1px solid rgba(159, 229, 192, 0.12);
  border-bottom: 0;
  border-radius: 22px 22px 0 0;
}

.memory-stack-label {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.35rem 0.25rem 1.1rem;
  color: #718278;
  font-family: var(--utility);
  font-size: 0.58rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.memory-cards {
  display: grid;
  gap: 0.65rem;
}

.memory-card {
  --card-index: 0;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 1rem;
  align-items: center;
  min-height: 112px;
  padding: 1.15rem;
  background: color-mix(in srgb, var(--canvas-raised) calc(100% - var(--card-index) * 7%), #243c31);
  border: 1px solid var(--line);
  border-radius: 19px;
  transition:
    transform 220ms ease,
    border-color 220ms ease,
    background-color 220ms ease;
}

.memory-card:hover {
  border-color: rgba(159, 229, 192, 0.34);
  transform: translateX(-7px);
}

.memory-card-number {
  color: var(--coral);
  font-family: var(--utility);
  font-size: 0.64rem;
}

.memory-card-label {
  color: var(--mint);
  font-family: var(--utility);
  font-size: 0.56rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.memory-card h3 {
  margin: 0.35rem 0 0;
  font-family: var(--display);
  font-size: clamp(1.18rem, 2vw, 1.52rem);
  font-weight: 400;
  letter-spacing: -0.025em;
  line-height: 1.08;
}

.memory-card p {
  margin: 0.45rem 0 0;
  color: #788a7f;
  font-size: 0.72rem;
}

.memory-card > svg {
  color: #617168;
}

.memory-stack-note {
  margin: 1rem 0 0.1rem;
  color: #718278;
  font-size: 0.72rem;
  text-align: center;
}

/* Workflow */

.workflow {
  background: var(--canvas);
}

.workflow-console {
  display: grid;
  overflow: hidden;
  grid-template-columns: minmax(300px, 0.36fr) minmax(0, 0.64fr);
  min-height: 610px;
  background: #0a1712;
  border: 1px solid var(--line);
  border-radius: 32px;
  box-shadow: var(--shadow);
}

.workflow-controls {
  display: grid;
  align-content: center;
  padding: 1.1rem;
  background: linear-gradient(180deg, rgba(241, 244, 237, 0.02), transparent);
  border-right: 1px solid var(--line);
}

.workflow-step {
  position: relative;
  display: grid;
  width: 100%;
  grid-template-columns: 28px 40px 1fr auto;
  gap: 0.7rem;
  align-items: center;
  padding: 1rem 0.9rem;
  color: #809086;
  background: transparent;
  border-bottom: 1px solid var(--line);
  text-align: left;
  cursor: pointer;
  transition:
    color 180ms ease,
    background-color 180ms ease;
}

.workflow-step:first-child {
  border-top: 1px solid var(--line);
}

.workflow-step::before {
  position: absolute;
  top: 8px;
  bottom: 8px;
  left: -1.1rem;
  width: 3px;
  content: "";
  background: var(--coral);
  border-radius: 99px;
  opacity: 0;
  transition: opacity 180ms ease;
}

.workflow-step:hover,
.workflow-step.is-active {
  color: var(--mist);
  background: rgba(241, 244, 237, 0.035);
}

.workflow-step.is-active::before {
  opacity: 1;
}

.workflow-step-index {
  font-family: var(--utility);
  font-size: 0.58rem;
}

.workflow-step-icon {
  display: inline-flex;
  width: 38px;
  height: 38px;
  align-items: center;
  justify-content: center;
  color: #8ea096;
  background: rgba(241, 244, 237, 0.05);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.workflow-step.is-active .workflow-step-icon {
  color: var(--canvas);
  background: var(--mint);
  border-color: var(--mint);
}

.workflow-step-copy {
  display: grid;
  gap: 3px;
}

.workflow-step-copy small {
  color: #75867b;
  font-family: var(--utility);
  font-size: 0.55rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.workflow-step-copy strong {
  font-size: 0.95rem;
  font-weight: 590;
}

.workflow-step > svg {
  opacity: 0;
  transition:
    opacity 180ms ease,
    transform 180ms ease;
}

.workflow-step.is-active > svg {
  opacity: 1;
  transform: translate(2px, -2px);
}

.workflow-stage {
  position: relative;
  overflow: hidden;
  min-height: 610px;
  isolation: isolate;
}

.workflow-picture,
.workflow-image {
  width: 100%;
  height: 100%;
}

.workflow-picture {
  position: absolute;
  z-index: -2;
  inset: 0;
}

.workflow-image {
  object-fit: cover;
  animation: stage-arrive 520ms cubic-bezier(0.2, 0.72, 0.2, 1) both;
}

.workflow-stage-overlay {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(8, 19, 15, 0.02) 22%, rgba(8, 19, 15, 0.88) 94%),
    linear-gradient(90deg, rgba(8, 19, 15, 0.16), transparent 62%);
}

.workflow-stage-copy {
  position: absolute;
  right: clamp(1.4rem, 4vw, 3.5rem);
  bottom: clamp(1.4rem, 4vw, 3.5rem);
  left: clamp(1.4rem, 4vw, 3.5rem);
  max-width: 620px;
  animation: copy-arrive 480ms 80ms cubic-bezier(0.2, 0.72, 0.2, 1) both;
}

.workflow-stage-label {
  display: inline-flex;
  padding: 0.45rem 0.7rem;
  color: var(--canvas);
  background: var(--mint);
  border-radius: 999px;
  font-family: var(--utility);
  font-size: 0.56rem;
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.workflow-stage-copy h3 {
  margin: 1rem 0 0;
  font-family: var(--display);
  font-size: clamp(2.5rem, 5vw, 5.1rem);
  font-weight: 400;
  letter-spacing: -0.05em;
  line-height: 0.92;
}

.workflow-stage-copy p {
  max-width: 570px;
  margin: 1rem 0 0;
  color: #d5ddd6;
  font-size: clamp(0.94rem, 1.3vw, 1.1rem);
  line-height: 1.55;
}

.workflow-stage-copy small {
  display: block;
  margin-top: 0.9rem;
  color: #94a399;
  font-size: 0.72rem;
}

.workflow-rail {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 1rem;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.workflow-rail span {
  display: flex;
  gap: 0.65rem;
  align-items: center;
  padding: 0.9rem 0.75rem;
  color: #7b8d81;
  border-right: 1px solid var(--line);
  font-family: var(--utility);
  font-size: 0.58rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.workflow-rail span:last-child {
  border-right: 0;
}

.workflow-rail b {
  color: var(--coral);
  font-weight: 650;
}

/* Promise */

.promise {
  padding-inline: 0;
}

.promise-shell {
  position: relative;
  overflow: hidden;
  min-height: min(860px, 88svh);
  isolation: isolate;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.promise-picture,
.promise-image {
  width: 100%;
  height: 100%;
}

.promise-picture {
  position: absolute;
  z-index: -2;
  inset: 0;
}

.promise-image {
  object-fit: cover;
  object-position: center;
  transform: scale(1.02);
}

.promise-overlay {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(8, 19, 15, 0.1), rgba(8, 19, 15, 0.2) 44%, rgba(8, 19, 15, 0.92)),
    linear-gradient(90deg, rgba(8, 19, 15, 0.75), transparent 55%);
}

.promise-topline {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  display: flex;
  justify-content: space-between;
  padding: 1.2rem clamp(1.25rem, 4vw, 4rem);
  color: rgba(241, 244, 237, 0.72);
  border-bottom: 1px solid rgba(241, 244, 237, 0.22);
  font-family: var(--utility);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.promise-content {
  display: grid;
  width: min(100% - 2.5rem, 1240px);
  min-height: min(860px, 88svh);
  grid-template-columns: minmax(0, 1.1fr) minmax(340px, 0.65fr);
  gap: 2rem;
  align-items: end;
  margin-inline: auto;
  padding: 7rem 0 4rem;
}

.promise-number {
  margin: 0;
  color: rgba(241, 244, 237, 0.95);
  font-size: clamp(8rem, 25vw, 23rem);
  font-weight: 760;
  letter-spacing: -0.1em;
  line-height: 0.68;
  text-shadow: 0 20px 80px rgba(0, 0, 0, 0.25);
}

.promise-copy {
  align-self: end;
  padding-bottom: 0.2rem;
}

.promise-copy .eyebrow {
  color: var(--mist);
}

.promise-copy h2 {
  max-width: 540px;
  font-size: clamp(2.7rem, 4.8vw, 5rem);
}

.promise-copy > p:not(.eyebrow) {
  max-width: 510px;
  margin: 1.4rem 0 0;
  color: #d3dbd4;
  font-size: 1rem;
  line-height: 1.65;
}

.promise-copy a {
  display: inline-flex;
  gap: 0.65rem;
  align-items: center;
  margin-top: 1.8rem;
  padding-bottom: 0.45rem;
  color: var(--mist);
  border-bottom: 1px solid rgba(241, 244, 237, 0.45);
  font-size: 0.85rem;
  font-weight: 650;
}

.promise-copy a:hover {
  border-color: var(--mint);
}

/* iOS */

.ios-section {
  overflow: hidden;
  color: #102019;
  background: var(--fog);
}

.ios-section .eyebrow {
  color: #35664f;
}

.ios-section .section-lead {
  color: #4f6257;
}

.ios-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.76fr) minmax(520px, 1fr);
  gap: clamp(3rem, 8vw, 8rem);
  align-items: center;
}

.ios-copy h2 {
  max-width: 600px;
}

.ios-benefits {
  display: grid;
  margin-top: 2.6rem;
  border-top: 1px solid rgba(16, 32, 25, 0.16);
}

.ios-benefit {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 0.9rem;
  align-items: center;
  padding: 1rem 0;
  border-bottom: 1px solid rgba(16, 32, 25, 0.16);
}

.ios-benefit > span {
  display: inline-flex;
  width: 38px;
  height: 38px;
  align-items: center;
  justify-content: center;
  color: #15261f;
  background: rgba(16, 32, 25, 0.08);
  border-radius: 13px;
}

.ios-benefit h3 {
  margin: 0;
  font-size: 0.92rem;
  font-weight: 690;
}

.ios-benefit p {
  margin: 0.25rem 0 0;
  color: #5f7066;
  font-size: 0.8rem;
  line-height: 1.45;
}

.ios-link {
  display: inline-flex;
  gap: 0.4rem;
  align-items: center;
  margin-top: 1.6rem;
  color: #183a2d;
  font-size: 0.86rem;
  font-weight: 690;
}

.ios-link svg {
  transition: transform 180ms ease;
}

.ios-link:hover svg {
  transform: translateX(4px);
}

.ios-visual {
  position: relative;
  overflow: hidden;
  min-height: 690px;
  background: #1b3229;
  border: 1px solid rgba(16, 32, 25, 0.2);
  border-radius: 38px;
  box-shadow: 0 30px 90px rgba(21, 38, 31, 0.18);
  isolation: isolate;
}

.ios-backdrop,
.ios-backdrop-image {
  width: 100%;
  height: 100%;
}

.ios-backdrop {
  position: absolute;
  z-index: -2;
  inset: 0;
}

.ios-backdrop-image {
  object-fit: cover;
}

.ios-backdrop-wash {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(8, 19, 15, 0.04), rgba(8, 19, 15, 0.56)),
    radial-gradient(circle at 50% 48%, transparent 20%, rgba(8, 19, 15, 0.28) 86%);
}

.phone-frame {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(330px, 70%);
  aspect-ratio: 0.52;
  padding: 9px;
  background: #07100d;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 52px;
  box-shadow:
    0 35px 90px rgba(0, 0, 0, 0.42),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  transform: translate(-50%, -49%) rotate(2deg);
  animation: phone-float 6.4s ease-in-out infinite;
}

.phone-island {
  position: absolute;
  z-index: 4;
  top: 18px;
  left: 50%;
  width: 32%;
  height: 24px;
  background: #020504;
  border-radius: 99px;
  transform: translateX(-50%);
}

.phone-screen {
  position: relative;
  overflow: hidden;
  width: 100%;
  height: 100%;
  background: #162b22;
  border-radius: 44px;
}

.phone-status {
  position: absolute;
  z-index: 3;
  top: 13px;
  right: 19px;
  left: 19px;
  display: flex;
  justify-content: space-between;
  color: white;
  font-size: 0.58rem;
  font-weight: 650;
}

.phone-wallpaper-picture,
.phone-wallpaper {
  width: 100%;
  height: 100%;
}

.phone-wallpaper-picture {
  position: absolute;
  inset: 0;
}

.phone-wallpaper {
  object-fit: cover;
  object-position: 54% center;
}

.share-panel {
  position: absolute;
  right: 9px;
  bottom: 10px;
  left: 9px;
  padding: 0.7rem 0.75rem 0.85rem;
  color: #102019;
  background: rgba(239, 244, 240, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.62);
  border-radius: 26px;
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(22px) saturate(130%);
}

.share-panel-handle {
  width: 34px;
  height: 4px;
  margin: 0 auto 0.75rem;
  background: rgba(16, 32, 25, 0.2);
  border-radius: 99px;
}

.share-panel-title {
  display: grid;
  grid-template-columns: 38px 1fr 26px;
  gap: 0.6rem;
  align-items: center;
}

.share-app-icon {
  display: inline-flex;
  width: 38px;
  height: 38px;
  align-items: center;
  justify-content: center;
  color: white;
  background: #183a2d;
  border-radius: 12px;
}

.share-panel-title small,
.share-panel-title strong {
  display: block;
}

.share-panel-title small {
  color: #64756b;
  font-size: 0.56rem;
}

.share-panel-title strong {
  margin-top: 2px;
  font-size: 0.78rem;
}

.share-check {
  display: inline-flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  color: #102019;
  background: var(--mint);
  border-radius: 50%;
}

.share-progress {
  overflow: hidden;
  height: 4px;
  margin-top: 0.8rem;
  background: rgba(16, 32, 25, 0.12);
  border-radius: 99px;
}

.share-progress span {
  display: block;
  width: 72%;
  height: 100%;
  background: #ff7351;
  border-radius: inherit;
  animation: save-progress 3.8s ease-in-out infinite;
}

.share-panel p {
  margin: 0.55rem 0 0;
  color: #53655b;
  font-size: 0.58rem;
}

.ios-illustration-label {
  position: absolute;
  right: 1rem;
  bottom: 1rem;
  left: 1rem;
  margin: 0;
  color: rgba(241, 244, 237, 0.7);
  font-family: var(--utility);
  font-size: 0.52rem;
  letter-spacing: 0.08em;
  text-align: center;
  text-transform: uppercase;
}

/* Pricing */

.pricing {
  background:
    radial-gradient(circle at 80% 36%, rgba(255, 115, 81, 0.08), transparent 25rem),
    var(--canvas);
}

.pricing-heading h2 {
  max-width: 800px;
}

.pricing-grid {
  display: grid;
  max-width: 980px;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-inline: auto;
}

.pricing-card {
  position: relative;
  display: flex;
  min-height: 620px;
  flex-direction: column;
  padding: clamp(1.5rem, 4vw, 2.7rem);
  background: rgba(241, 244, 237, 0.025);
  border: 1px solid var(--line);
  border-radius: 28px;
}

.pricing-card.is-featured {
  background:
    linear-gradient(180deg, rgba(255, 115, 81, 0.11), transparent 34%),
    var(--canvas-raised);
  border-color: rgba(255, 115, 81, 0.38);
  box-shadow: 0 32px 90px rgba(0, 0, 0, 0.25);
}

.pricing-badge {
  position: absolute;
  top: 1.2rem;
  right: 1.2rem;
  display: inline-flex;
  gap: 0.35rem;
  align-items: center;
  padding: 0.45rem 0.65rem;
  color: #102019;
  background: var(--mint);
  border-radius: 999px;
  font-family: var(--utility);
  font-size: 0.52rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pricing-plan {
  margin: 0;
  color: var(--mint);
  font-family: var(--utility);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.pricing-price {
  display: flex;
  gap: 0.8rem;
  align-items: end;
  margin-top: 2rem;
}

.pricing-price span {
  font-family: var(--display);
  font-size: clamp(4.2rem, 8vw, 7rem);
  font-weight: 400;
  letter-spacing: -0.07em;
  line-height: 0.72;
}

.pricing-price small {
  padding-bottom: 0.4rem;
  color: #88998e;
  font-size: 0.76rem;
}

.billing-note {
  margin: 1rem 0 0;
  color: #74867b;
  font-family: var(--utility);
  font-size: 0.58rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.pricing-description {
  min-height: 50px;
  margin: 1.8rem 0 0;
  color: #a5b2a9;
  line-height: 1.55;
}

.pricing-features {
  display: grid;
  gap: 0.8rem;
  padding: 1.7rem 0 0;
  margin: 1.8rem 0 2.2rem;
  border-top: 1px solid var(--line);
  list-style: none;
}

.pricing-features li {
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 0.7rem;
  align-items: center;
  color: #aebbb2;
  font-size: 0.84rem;
}

.pricing-features li span {
  display: inline-flex;
  width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  color: var(--canvas);
  background: rgba(159, 229, 192, 0.88);
  border-radius: 50%;
}

.pricing-button {
  width: 100%;
  min-height: 50px;
  margin-top: auto;
}

/* FAQ */

.faq {
  background: var(--canvas-soft);
  border-top: 1px solid var(--line);
}

.faq-grid {
  display: grid;
  grid-template-columns: minmax(280px, 0.62fr) minmax(0, 1fr);
  gap: clamp(3rem, 8vw, 8rem);
  align-items: start;
}

.faq-heading {
  position: sticky;
  top: 120px;
}

.faq-heading h2 {
  max-width: 500px;
}

.faq-heading a {
  display: inline-flex;
  margin-top: 1.8rem;
  padding-bottom: 0.4rem;
  color: var(--mist);
  border-bottom: 1px solid var(--line-strong);
  font-size: 0.84rem;
  font-weight: 650;
}

.faq-list {
  border-top: 1px solid var(--line);
}

.faq-list details {
  border-bottom: 1px solid var(--line);
}

.faq-list summary {
  display: grid;
  grid-template-columns: 1fr 30px;
  gap: 1rem;
  align-items: center;
  padding: 1.45rem 0;
  color: #dfe6df;
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  font-weight: 570;
  list-style: none;
  cursor: pointer;
}

.faq-list summary::-webkit-details-marker {
  display: none;
}

.faq-icon {
  position: relative;
  width: 28px;
  height: 28px;
  background: rgba(241, 244, 237, 0.05);
  border: 1px solid var(--line);
  border-radius: 50%;
  transition:
    background-color 180ms ease,
    transform 220ms ease;
}

.faq-icon::before,
.faq-icon::after {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 10px;
  height: 1px;
  content: "";
  background: var(--mist);
  transform: translate(-50%, -50%);
}

.faq-icon::after {
  transform: translate(-50%, -50%) rotate(90deg);
}

.faq-list details[open] .faq-icon {
  background: var(--coral);
  border-color: var(--coral);
  transform: rotate(45deg);
}

.faq-answer {
  overflow: hidden;
}

.faq-answer p {
  max-width: 700px;
  padding: 0 3.5rem 1.5rem 0;
  margin: 0;
  color: #91a097;
  font-size: 0.9rem;
  line-height: 1.68;
}

/* Footer */

.site-footer {
  padding: 1.25rem 1.25rem 1.5rem;
  color: var(--mist);
  background: var(--canvas);
}

.closing-cta {
  position: relative;
  display: grid;
  overflow: hidden;
  min-height: 430px;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 2rem;
  align-items: end;
  padding: clamp(2rem, 5vw, 4.5rem);
  background:
    radial-gradient(circle at 78% 24%, rgba(255, 115, 81, 0.28), transparent 22rem),
    linear-gradient(135deg, #17382b, #0b1914 64%);
  border: 1px solid var(--line);
  border-radius: 34px;
  isolation: isolate;
}

.closing-portal {
  position: absolute;
  z-index: -1;
  top: -40%;
  right: 7%;
  width: min(44vw, 500px);
  aspect-ratio: 0.78;
  border: 1px solid rgba(159, 229, 192, 0.34);
  border-bottom: 0;
  border-radius: 50% 50% 0 0;
}

.closing-portal span {
  position: absolute;
  inset: 7%;
  border: 1px solid rgba(159, 229, 192, 0.22);
  border-bottom: 0;
  border-radius: inherit;
}

.closing-portal span:nth-child(2) {
  inset: 14%;
}

.closing-portal span:nth-child(3) {
  inset: 21%;
  border-color: rgba(255, 115, 81, 0.35);
}

.closing-copy {
  align-self: end;
}

.closing-copy h2 {
  max-width: 790px;
  font-size: clamp(3.2rem, 7vw, 7.7rem);
}

.closing-copy > p:last-child {
  margin: 1.2rem 0 0;
  color: #a8b5ac;
  font-size: clamp(1rem, 1.5vw, 1.2rem);
}

.closing-button {
  min-width: 180px;
  min-height: 52px;
  color: var(--canvas);
  background: var(--mist);
}

.closing-button:hover {
  color: var(--canvas);
  background: var(--mint);
}

.footer-main {
  display: grid;
  grid-template-columns: minmax(230px, 0.75fr) minmax(0, 1fr);
  gap: clamp(3rem, 8vw, 8rem);
  padding: 5rem 0 4rem;
}

.footer-brand-block p {
  margin: 1rem 0 0;
  color: #7c8e82;
  font-size: 0.86rem;
}

.footer-sign-in {
  display: inline-flex;
  gap: 0.4rem;
  align-items: center;
  margin-top: 1.5rem;
  color: var(--mist);
  font-size: 0.8rem;
  font-weight: 650;
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.footer-links nav {
  display: grid;
  align-content: start;
  gap: 0.85rem;
}

.footer-links h3 {
  margin: 0 0 0.25rem;
  color: #596b60;
  font-family: var(--utility);
  font-size: 0.57rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.footer-links a {
  width: fit-content;
  color: #899a8f;
  font-size: 0.8rem;
  transition: color 160ms ease;
}

.footer-links a:hover {
  color: var(--mist);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding-top: 1.2rem;
  color: #56675c;
  border-top: 1px solid var(--line);
  font-family: var(--utility);
  font-size: 0.54rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.footer-bottom p {
  margin: 0;
}

/* Motion */

@keyframes cinematic-drift {
  0% {
    transform: scale(1.045) translate3d(-0.8%, 0, 0);
  }
  100% {
    transform: scale(1.09) translate3d(1%, -0.8%, 0);
  }
}

@keyframes portal-breathe {
  0%,
  100% {
    opacity: 0.46;
    transform: scale(0.985);
  }
  50% {
    opacity: 0.9;
    transform: scale(1.01);
  }
}

@keyframes float-one {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(-1deg);
  }
  50% {
    transform: translate3d(0, -8px, 0) rotate(0.5deg);
  }
}

@keyframes float-two {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(0.5deg);
  }
  50% {
    transform: translate3d(0, 9px, 0) rotate(-0.5deg);
  }
}

@keyframes scroll-prompt {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(5px);
  }
}

@keyframes stage-arrive {
  from {
    opacity: 0.4;
    transform: scale(1.05);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes copy-arrive {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes phone-float {
  0%,
  100% {
    transform: translate(-50%, -49%) rotate(2deg);
  }
  50% {
    transform: translate(-50%, -51%) rotate(1deg);
  }
}

@keyframes save-progress {
  0%,
  10% {
    width: 12%;
  }
  70%,
  100% {
    width: 100%;
  }
}

/* Responsive */

@media (max-width: 1080px) {
  .hero-shell {
    grid-template-columns: minmax(0, 1fr) minmax(400px, 0.78fr);
    gap: 2.5rem;
  }

  .hero h1 {
    font-size: clamp(3.5rem, 7.8vw, 6.6rem);
  }

  .transformation-grid,
  .ios-grid {
    gap: 4rem;
  }

  .ios-grid {
    grid-template-columns: minmax(0, 0.72fr) minmax(450px, 1fr);
  }

  .promise-content {
    grid-template-columns: 1fr;
    align-content: end;
  }

  .promise-number {
    align-self: end;
  }

  .promise-copy {
    max-width: 650px;
  }
}

@media (max-width: 900px) {
  .desktop-nav,
  .header-sign-in,
  .header-cta {
    display: none;
  }

  .header-shell {
    grid-template-columns: 1fr auto;
  }

  .menu-button {
    display: inline-flex;
  }

  .hero {
    padding-top: 8rem;
  }

  .hero-shell {
    grid-template-columns: 1fr;
    gap: 4.5rem;
  }

  .hero-copy {
    max-width: 760px;
    padding-left: 0;
  }

  .hero h1 {
    font-size: clamp(4rem, 12vw, 7rem);
  }

  .hero-visual {
    width: min(100%, 610px);
    margin-inline: auto;
  }

  .hero-scroll {
    display: none;
  }

  .transformation-grid,
  .ios-grid,
  .faq-grid {
    grid-template-columns: 1fr;
  }

  .memory-stack {
    max-width: 720px;
  }

  .workflow-console {
    grid-template-columns: 1fr;
  }

  .workflow-controls {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    padding: 0.75rem;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .workflow-step {
    display: flex;
    min-height: 92px;
    flex-direction: column;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.7rem 0.35rem;
    border-right: 1px solid var(--line);
    border-bottom: 0;
    text-align: center;
  }

  .workflow-step:first-child {
    border-top: 0;
  }

  .workflow-step:last-child {
    border-right: 0;
  }

  .workflow-step::before {
    top: auto;
    right: 8px;
    bottom: -0.75rem;
    left: 8px;
    width: auto;
    height: 3px;
  }

  .workflow-step-index,
  .workflow-step > svg {
    display: none;
  }

  .workflow-step-icon {
    width: 34px;
    height: 34px;
  }

  .workflow-step-copy strong {
    font-size: 0.75rem;
  }

  .workflow-stage {
    min-height: 560px;
  }

  .ios-copy {
    max-width: 720px;
  }

  .ios-visual {
    width: min(100%, 720px);
    margin-inline: auto;
  }

  .faq-heading {
    position: static;
  }

  .footer-main {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .section {
    padding: 5.5rem 1rem;
  }

  .section-heading {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .section-heading .section-lead {
    margin-top: 0;
  }

  .site-header {
    padding-inline: 0.75rem;
  }

  .mobile-nav {
    width: calc(100% - 1.5rem);
  }

  .hero {
    min-height: auto;
    padding: 7.5rem 1rem 5rem;
  }

  .hero-eyebrow {
    margin-bottom: 1.6rem;
  }

  .hero h1 {
    font-size: clamp(3.35rem, 16vw, 6.2rem);
    line-height: 0.84;
    white-space: normal;
    overflow-wrap: anywhere;
  }

  .hero-promise {
    margin-top: 1.5rem;
  }

  .hero-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-visual {
    padding-inline: 0.45rem;
  }

  .hero-portal-line {
    inset-inline: -0.2rem;
  }

  .save-toast {
    top: 12%;
    left: 4%;
  }

  .return-card {
    right: 3%;
    bottom: 7%;
    max-width: 245px;
  }

  .transformation-grid {
    gap: 4rem;
  }

  .memory-card {
    grid-template-columns: auto 1fr;
  }

  .memory-card > svg {
    display: none;
  }

  .workflow-console {
    min-height: auto;
    border-radius: 24px;
  }

  .workflow-controls {
    overflow-x: auto;
    grid-template-columns: repeat(4, minmax(92px, 1fr));
    scrollbar-width: none;
  }

  .workflow-controls::-webkit-scrollbar {
    display: none;
  }

  .workflow-stage {
    min-height: 500px;
  }

  .workflow-stage-copy p {
    font-size: 0.9rem;
  }

  .workflow-rail {
    grid-template-columns: repeat(2, 1fr);
  }

  .workflow-rail span:nth-child(2) {
    border-right: 0;
  }

  .workflow-rail span:nth-child(-n + 2) {
    border-bottom: 1px solid var(--line);
  }

  .promise-shell,
  .promise-content {
    min-height: 760px;
  }

  .promise-content {
    grid-template-columns: 1fr;
    padding: 6rem 0 3rem;
  }

  .promise-number {
    align-self: end;
    font-size: clamp(7rem, 37vw, 13rem);
  }

  .promise-copy h2 {
    font-size: clamp(2.6rem, 13vw, 4.6rem);
  }

  .promise-topline span:last-child {
    display: none;
  }

  .ios-grid {
    gap: 3.2rem;
  }

  .ios-visual {
    min-height: 600px;
    border-radius: 28px;
  }

  .phone-frame {
    width: min(300px, 74%);
  }

  .pricing-grid {
    grid-template-columns: 1fr;
  }

  .pricing-card {
    min-height: 580px;
  }

  .faq-answer p {
    padding-right: 0.4rem;
  }

  .closing-cta {
    min-height: 510px;
    grid-template-columns: 1fr;
    align-content: end;
    padding: 2rem 1.5rem;
  }

  .closing-button {
    width: 100%;
  }

  .closing-portal {
    top: -8%;
    right: -5%;
    width: 80vw;
  }

  .footer-links {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-bottom {
    flex-direction: column;
  }
}

@media (max-width: 520px) {
  .hero-visual {
    margin-top: -1rem;
  }

  .hero-image-frame {
    aspect-ratio: 0.74;
  }

  .save-toast,
  .return-card {
    gap: 0.55rem;
    padding: 0.6rem 0.65rem;
    border-radius: 13px;
  }

  .save-toast-icon,
  .return-card-icon {
    width: 31px;
    height: 31px;
  }

  .save-toast span,
  .return-card span {
    font-size: 0.67rem;
  }

  .return-card {
    max-width: 215px;
  }

  .workflow-step-copy small {
    display: none;
  }

  .workflow-stage {
    min-height: 470px;
  }

  .workflow-stage-copy small {
    display: none;
  }

  .ios-visual {
    min-height: 540px;
  }

  .phone-frame {
    width: 275px;
    max-width: 78%;
  }

  .footer-links {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }

  .reveal-ready [data-reveal] {
    opacity: 1;
    transform: none;
  }
}

